import {createVideoScrubber} from './video-scrubber.js';
import {bandon} from './bandon-data.js';
import {holeState,mapPoints,mapDistance,requestedHole,flightProgress,teeNames,teeColors} from './bandon-model.js';
const params=new URLSearchParams(location.search),legacy=params.get('view');
if(legacy&&legacy!=='journey')location.replace(`dashboard.html${location.search}`);
const $=s=>document.querySelector(s),reduced=matchMedia('(prefers-reduced-motion: reduce)');
let hole=requestedHole(location.search),tee=4,metric='yardage',motion=!reduced.matches,quality='hd',progress=0,ready=false,frame=0;
const video=$('#flight-video');
const scrubber=createVideoScrubber(video,()=>{video.classList.add('ready');$('#flight-status').hidden=true;});
function media(h,kind){return `assets/bandon/${kind}-${String(h).padStart(2,'0')}`;}
function announce(text){$('#announcement').textContent=text;}
function setHole(h,{updateUrl=true,reset=true}={}){if(h<1||h>18)return;hole=h;progress=0;ready=false;scrubber.reset();video.classList.remove('ready');video.pause();$('#flight-poster').src=media(h,'hole')+'.jpg';$('#flight-poster').alt=`Bandon Dunes hole ${h} aerial view`;$('#map-art').setAttribute('href',media(h,'hole')+'.svg');video.src=media(h,'flight')+(quality==='sd'?'-sd':'')+'.mp4'+(h===1?'?v=complete-green-2':'');video.load();$('#flight-status').textContent=`Loading hole ${h}…`;$('#flight-status').hidden=false;$('#hole-number').textContent=h;$('#hole-par').textContent=`PAR ${bandon.holePar[h]}`;$('#previous-hole').disabled=h===1;$('#next-hole').disabled=h===18;$('#map-shot').style.display='none';$('#holes-dialog').close();if(updateUrl){const url=new URL(location.href);url.searchParams.delete('view');url.searchParams.set('hole',h);history.pushState({hole:h},'',url);}if(reset)window.scrollTo({top:0,behavior:'instant'});updateCourseInfo();renderScorecard();renderMap();announce(`Bandon Dunes hole ${h}, par ${bandon.holePar[h]}`);schedule();}
function updateCourseInfo(){const s=holeState(hole,tee);$('#description-meta').textContent=`HOLE ${hole} · PAR ${s.par} · ${s.yards} YARDS · ${s.teeName.toUpperCase()} TEES`;$('#description-copy').textContent=`Explore this ${s.yards}-yard par ${s.par} from tee to green. Select a different tee color, jump to another hole, or point at the hole map for a distance preview.`;document.title=`Hole ${hole} · Bandon Dunes · Fairway Flow`;}
function renderMap(){const selected=mapPoints(hole,tee);$('#map-tees').innerHTML=Array.from({length:6},(_,i)=>{const t=i+1,p=mapPoints(hole,t).tee;return `<g data-tee="${t}" role="button" tabindex="0" aria-label="${teeNames[i]} tees, ${bandon.yardages[t][hole]} yards" transform="translate(${p.x} ${p.y})"><rect x="${t===tee?-25:-5}" y="-10" width="${t===tee?50:10}" height="${t===tee?29:10}" rx="2" fill="${t===tee?teeColors[i]:'#e6e1bc'}" stroke="#fff" stroke-width="${t===tee?1:0}"/>${t===tee?`<text text-anchor="middle" y="10" fill="white" font-size="18" font-family="sans-serif">${bandon.yardages[t][hole]}</text>`:''}</g>`;}).join('');$('#pin-marker').innerHTML=`<g transform="translate(${selected.pin.x} ${selected.pin.y})"><ellipse rx="7" ry="3" fill="#fff"/><path d="M0 0v-36l25 8-25 9" stroke="white" stroke-width="2" fill="white"/></g>`;const yardage=bandon.yardages[4][hole];$('#yard-grid').innerHTML=Array.from({length:Math.floor(yardage/50)},(_,i)=>`<div class="yard-line" style="bottom:${11+(i+1)*50/yardage*68}%"><span>${(i+1)*50}</span></div>`).join('');}
function setTee(t){if(t<1||t>6)return;tee=t;renderMap();renderScorecard();updateCourseInfo();$('#map-shot').style.display='none';announce(`${teeNames[t-1]} tees selected, ${bandon.yardages[t][hole]} yards`);}
function renderScorecard(){$('#tee-selector').innerHTML=teeNames.map((name,i)=>`<button data-tee="${i+1}" style="--tee:${teeColors[i]}" aria-pressed="${tee===i+1}" aria-label="${name} tees, ${bandon.courseYardage[i]} yards"><b>${bandon.courseYardage[i]}</b></button>`).join('');$('#score-graph').innerHTML=Array.from({length:18},(_,i)=>{const h=i+1,value=metric==='yardage'?bandon.yardages[tee][h]:bandon.holeHandicap[h],height=metric==='yardage'?value/650*100:(19-value)/18*100;return `<button class="score-bar" data-hole="${h}" style="--tee:${teeColors[tee-1]}" aria-current="${h===hole}" aria-label="Hole ${h}, ${metric} ${value}"><em>${value}</em><span style="height:${height}%"></span><small>${h}</small></button>`;}).join('');$('#score-table').innerHTML=`<thead><tr><th>HOLE</th>${Array.from({length:18},(_,i)=>`<th><button data-hole="${i+1}">${i+1}</button></th>`).join('')}<th>TOTAL</th></tr></thead><tbody><tr><th>${teeNames[tee-1].toUpperCase()}</th>${bandon.yardages[tee].slice(1).map(y=>`<td>${y}</td>`).join('')}<td>${bandon.yardages[tee].slice(1).reduce((a,b)=>a+b,0)}</td></tr><tr><th>PAR</th>${bandon.holePar.slice(1).map(p=>`<td>${p}</td>`).join('')}<td>${bandon.holePar.slice(1).reduce((a,b)=>a+b,0)}</td></tr><tr><th>HDCP</th>${bandon.holeHandicap.slice(1).map(p=>`<td>${p}</td>`).join('')}<td>—</td></tr></tbody>`;}
function showTab(tab){for(const key of ['scorecard','map','courses']){$('#'+key+'-panel').hidden=key!==tab;document.querySelector(`[data-tab="${key}"]`).setAttribute('aria-selected',String(key===tab));}if(tab==='map'&&$('#course-map-frame').src==='about:blank')$('#course-map-frame').src='https://www.openstreetmap.org/export/embed.html?bbox=-124.408%2C43.178%2C-124.376%2C43.199&layer=mapnik&marker=43.187%2C-124.391';}
function toggleMenu(open){const next=open??$('#course-menu').hidden;$('#course-menu').hidden=!next;$('#menu-button').setAttribute('aria-expanded',String(next));$('#menu-button').setAttribute('aria-label',next?'Close course menu':'Open course menu');}
video.addEventListener('loadedmetadata',()=>{ready=true;schedule();});video.addEventListener('error',()=>{ready=false;$('#flight-status').textContent='Flyover unavailable. Hole map and tee yardages remain available.';$('#flight-status').hidden=false;});
function update(){frame=0;progress=flightProgress(window.scrollY,document.documentElement.scrollHeight,innerHeight);scrubber.setProgress(motion?progress:0);$('#video-progress-fill').style.width=progress*100+'%';$('#scroll-reminder').style.opacity=progress>.025?'0':'1';$('#map-camera').setAttribute('transform',`translate(0 ${800-progress*710})`);}
function schedule(){if(!frame)frame=requestAnimationFrame(update);}
function pointOnMap(e){if(e.target.closest('[data-tee]'))return;const svg=$('#hole-map');if(!svg.getScreenCTM())return;const pt=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());if(pt.x<0||pt.x>450||pt.y<0||pt.y>800)return;const p=mapPoints(hole,tee),d=mapDistance(hole,tee,pt);$('#map-shot').style.display='';$('#shot-lines').setAttribute('d',`M${p.tee.x} ${p.tee.y}L${pt.x} ${pt.y}L${p.pin.x} ${p.pin.y}`);$('#shot-point').setAttribute('cx',pt.x);$('#shot-point').setAttribute('cy',pt.y);for(const [id,value,from] of [['map-from-tee',d.fromTee,p.tee],['map-to-pin',d.toPin,p.pin]]){const el=$('#'+id);el.textContent=value;el.setAttribute('x',(from.x+pt.x)/2+8);el.setAttribute('y',(from.y+pt.y)/2);}}
$('#hole-map').addEventListener('pointermove',pointOnMap);$('#hole-map').addEventListener('pointerdown',pointOnMap);
$('#hole-tiles').innerHTML=Array.from({length:18},(_,i)=>`<button class="hole-tile" data-hole="${i+1}" style="background-image:url('${media(i+1,'hole')}.jpg')"><strong>${i+1}</strong><small>PAR ${bandon.holePar[i+1]}</small></button>`).join('');
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-tee]');if(!b)return;if(b.dataset.hole){setHole(+b.dataset.hole);toggleMenu(false);}if(b.dataset.tee)setTee(+b.dataset.tee);if(b.dataset.tab)showTab(b.dataset.tab);if(b.dataset.metric){metric=b.dataset.metric;document.querySelectorAll('[data-metric]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.metric===metric)));renderScorecard();}if(b.dataset.motion){motion=b.dataset.motion==='on';document.querySelectorAll('[data-motion]').forEach(el=>el.setAttribute('aria-pressed',String((el.dataset.motion==='on')===motion)));schedule();}if(b.dataset.quality){quality=b.dataset.quality;setHole(hole,{updateUrl:false,reset:false});document.querySelectorAll('[data-quality]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.quality===quality)));}switch(b.id){case 'info-button':document.body.classList.toggle('mobile-info');b.setAttribute('aria-expanded',String(document.body.classList.contains('mobile-info')));break;case 'hole-picker':$('#holes-dialog').showModal();break;case 'close-holes':$('#holes-dialog').close();break;case 'previous-hole':setHole(hole-1);break;case 'next-hole':setHole(hole+1);break;case 'menu-button':toggleMenu();break;case 'settings-button':$('#settings-panel').hidden=!$('#settings-panel').hidden;b.setAttribute('aria-expanded',String(!$('#settings-panel').hidden));break;case 'full-view':document.body.classList.toggle('full-view');b.textContent=document.body.classList.contains('full-view')?'EXIT FULL VIEW ↙':'FULL SCREEN ↗';break;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){toggleMenu(false);$('#settings-panel').hidden=true;document.body.classList.remove('full-view');}if(e.target.matches('[data-tee]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();setTee(+e.target.dataset.tee);}if(!['INPUT','SELECT','BUTTON','IFRAME'].includes(e.target.tagName)){if(e.key==='ArrowRight')setHole(Math.min(18,hole+1));if(e.key==='ArrowLeft')setHole(Math.max(1,hole-1));}});
window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule);window.addEventListener('popstate',()=>setHole(requestedHole(location.search),{updateUrl:false}));reduced.addEventListener('change',()=>{motion=!reduced.matches;schedule();});setHole(hole,{updateUrl:false});
